def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_my, last_op = history[-1]

    myD = 0
    oppD = 0
    for a, b in history:
        if a == 'D':
            myD += 1
        if b == 'D':
            oppD += 1

    oppC = n - oppD

    transCC = 0
    transCD = 0
    transDC = 0
    transDD = 0
    for i in range(1, n):
        pm = history[i - 1][0]
        co = history[i][1]
        if pm == 'D':
            if co == 'C':
                transDC += 1
            else:
                transDD += 1
        else:
            if co == 'C':
                transCC += 1
            else:
                transCD += 1

    dtrans = transDC + transDD
    if dtrans:
        pForgive = transDC / dtrans
    else:
        pForgive = 0.0

    ctrans = transCC + transCD
    if ctrans:
        pNice = transCC / ctrans
    else:
        pNice = 1.0

    start6 = n - 6
    if start6 < 0:
        start6 = 0
    start10 = n - 10
    if start10 < 0:
        start10 = 0

    recent6D = 0
    for i in range(start6, n):
        if history[i][1] == 'D':
            recent6D += 1

    recent10D = 0
    for i in range(start10, n):
        if history[i][1] == 'D':
            recent10D += 1

    d = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        d += 1
        i -= 1

    prior_n = n - d
    if prior_n > 0:
        prior_ratio = oppC / prior_n
    else:
        prior_ratio = 0.0

    coop_ratio = oppC / n

    if last_op == 'C':
        evidence = False
        if transDC >= 1 and oppD == 0:
            evidence = True
        elif transDC >= 2 and oppD <= max(3, n // 8) and recent10D <= 3:
            evidence = True
        elif pForgive >= 0.65 and oppD <= max(4, n // 5) and recent10D <= 4:
            evidence = True

        if evidence:
            return 'D'

        if oppD == 0 and myD == 0:
            p = 0.0
            if n >= 30:
                p = 0.01
            if n >= 70:
                p = 0.03
            if n >= 85:
                p = 0.15
            if n >= 92:
                p = 0.35
            if rng.random() < p:
                return 'D'

        return 'C'

    if (oppD > max(4, (n * 11) // 20)) or (coop_ratio < 0.40 and recent10D >= 6) or (prior_ratio < 0.35 and d > 3):
        if d > 8 and coop_ratio > 0.45 and pNice > 0.55 and recent10D < 10 and rng.random() < 0.02:
            return 'C'
        return 'D'

    if d <= 3 and prior_ratio > 0.55 and recent10D <= 6:
        return 'C'

    if last_my == 'D':
        if d > 3 and coop_ratio > 0.45 and pNice > 0.5 and recent10D <= 9 and rng.random() < 0.15:
            return 'C'
        if d > 3 and coop_ratio > 0.35 and oppD <= max(5, n // 2) and rng.random() < 0.22:
            return 'C'

    return 'D'
